    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        int[] quiet = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            quiet[i] = (int) in.nval;
        }
        int[][] richer = new int[m][2];
        for (int i = 0; i < m; i++) {
            in.nextToken();
            richer[i][0] = (int) in.nval;
            in.nextToken();
            richer[i][1] = (int) in.nval;
        }
        int[] ans = loudAndRich(richer, quiet);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < ans.length; i++) sb.append(ans[i]).append(i + 1 < ans.length ? " " : "\n");
        System.out.print(sb);
